// C++11: Using deleted functions (preferred)
class NonCopyable {
public:
  NonCopyable() = default;
  NonCopyable(const NonCopyable&) = delete; // Prohibit copying
  NonCopyable& operator=(const NonCopyable&) = delete; // Prohibit assignment
};

// C++98: Private and undefined idiom (legacy)
class LegacyNonCopyable {
private:
  LegacyNonCopyable(const LegacyNonCopyable&); // Not defined
  LegacyNonCopyable& operator=(const LegacyNonCopyable&); // Not defined
public:
  LegacyNonCopyable() {}
};

void test() {
  NonCopyable nc1;
  // NonCopyable nc2 = nc1; // COMPILE ERROR: use of deleted function
}
